// One Telegram message per row from script_approvals_due(). Telegram text is Vietnamese (D-061). Callback data stays under Telegram's
// 64-byte limit: a1:<A|G|R>:<32-hex token>.
// Episodes (D-050) are counted in acts and shots; Shorts in scenes.
const size = (script) => script.format === 'episode'
  ? `Tập ~${((script.total_seconds ?? 0) / 60).toFixed(1)} phút, ${script.act_count ?? '?'} hồi, ${script.shot_count ?? '?'} shot, ${script.line_count ?? '?'} câu thoại, ${script.narration_chars ?? '?'} ký tự lời đọc`
  : `${script.total_seconds ?? '?'} giây, ${script.scene_count ?? '?'} cảnh, ${script.narration_chars ?? '?'} ký tự lời đọc`;
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
return rows.map(({ json: row }) => {
  const script = (typeof row.script === 'string' ? JSON.parse(row.script) : row.script) || {};
  const shortId = String(row.video_id).slice(0, 8);
  const header = row.kind === 'REMINDER'
    ? '[AI Video] Nhắc: kịch bản đang chờ duyệt (A1)'
    : '[AI Video] Kịch bản sẵn sàng để duyệt (A1)';
  // tts_estimate is what approving accepts as the TTS budget (D-023); null means no price is set.
  const estimate = script.tts_estimate;
  const budget = estimate
    ? `Ngân sách TTS: tối đa ${estimate.amount} ${estimate.currency === 'CRD' ? 'credit ITERA' : estimate.currency} (${estimate.units} ký tự)`
    : 'Ngân sách TTS: không có (chưa cấu hình giá TTS); duyệt sẽ không cho chi tiền TTS';
  const text = [
    header,
    `Video ${shortId} v${row.version}`,
    `Tiêu đề: ${script.title ?? '?'}`,
    size(script),
    budget,
    '',
    String(script.preview ?? '').slice(0, 3000),
    '',
    `Hết hạn: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
    '',
    // Notes (D-070): WF-06 takes a reply to this message as notes for the request ending in kb:<token>.
    'Trả lời tin nhắn này bằng lời bình thường để sửa kịch bản.',
    `kb:${row.token}`,
  ].join('\n');
  return { json: { text, approve: `a1:A:${row.token}`, regenerate: `a1:G:${row.token}`, reject: `a1:R:${row.token}` } };
});

// One item per new A1 request with a script file (reminders send none): the worker serves script.md
// against the script job's media token (D-070). Replace the base URL on import. ASCII file name.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST');
return rows.flatMap(({ json: row }) => {
  const script = (typeof row.script === 'string' ? JSON.parse(row.script) : row.script) || {};
  const file = script.file;
  if (!file || typeof file.job_id !== 'string' || typeof file.token !== 'string') return [];
  const shortId = String(row.video_id).slice(0, 8);
  return [{
    json: {
      url: `${WORKER}/media/${row.video_id}/${row.version}/${file.job_id}/script.md?t=${file.token}`,
      fileName: `script-${shortId}-v${row.version}.md`,
      caption: `Kịch bản đầy đủ · Video ${shortId} v${row.version} · ${script.title ?? '?'}`.slice(0, 1024),
    },
  }];
});
